/* Tekrar havuzu: voc-verb, voc-adj, voc-adv, voc-noun, voc-phrasal */
PRACTICE.push(
  /* ---------- voc-verb ---------- */
  {id:"r-voc-verb-01", sub:"voc-verb", from:["w1-06","vocab-01"], q:"Critics argue that cutting funding for public libraries will only ---- existing inequalities in access to information.", o:["alleviate","endorse","exacerbate","ascertain","abandon"], a:2, e:"exacerbate = kötüleştirmek, şiddetlendirmek; eleştirmenlerin uyarısı olumsuz bir sonuç ister. alleviate (hafifletmek) tam tersi anlam verir ve “critics argue” tonuyla çelişir."},
  {id:"r-voc-verb-02", sub:"voc-verb", from:["vocab-02"], q:"Archaeologists were unable to ---- the exact age of the skeleton because the soil around it had been disturbed by later building work.", o:["determine","deteriorate","emerge","exaggerate","suspend"], a:0, e:"determine = belirlemek; “the exact age” nesnesiyle uyumludur. deteriorate ve emerge nesne almayan fiillerdir, exaggerate (abartmak) ise anlamca uymaz."},
  {id:"r-voc-verb-03", sub:"voc-verb", from:["vocab-04"], q:"Following reports of widespread fraud, the ministry announced that it would ---- all payments to the contractor pending a full investigation.", o:["accelerate","reward","accumulate","extend","suspend"], a:4, e:"suspend = askıya almak, geçici olarak durdurmak; “pending a full investigation” (soruşturma sonuçlanana kadar) bunu gösterir. accelerate (hızlandırmak) ve reward (ödüllendirmek) dolandırıcılık bağlamıyla çelişir."},
  {id:"r-voc-verb-04", sub:"voc-verb", from:["vocab-03"], q:"Rather than ---- the old textile factory, the town council converted it into a museum that now attracts thousands of visitors a year.", o:["imitate","demolish","advocate","resemble","illustrate"], a:1, e:"demolish = yıkmak; “rather than” müzeye dönüştürmeye karşıt bir seçenek ister. resemble (benzemek) ve imitate (taklit etmek) bu zıtlığı kurmaz."},
  {id:"r-voc-verb-05", sub:"voc-verb", from:["vocab-01","w1-01"], q:"Early warning systems cannot prevent earthquakes, but they can ---- the loss of life by giving people a few crucial seconds to take cover.", o:["accumulate","provoke","sustain","minimise","accelerate"], a:3, e:"minimise = en aza indirmek; insanlara sığınma için zaman tanımak can kaybını azaltır. provoke (kışkırtmak) ve accelerate (hızlandırmak) olumsuz sonuç verir, cümlenin olumlu tonuyla çelişir."},
  {id:"r-voc-verb-06", sub:"voc-verb", from:["vocab-03","w1-06"], q:"Engineers are testing a new coating designed to ---- the lifespan of wind turbine blades, which are often damaged by rain and hail.", o:["prolong","deteriorate","diminish","collapse","conceal"], a:0, e:"prolong = uzatmak; koruyucu kaplamanın amacı ömrü uzatmaktır. deteriorate ve collapse nesne almaz, diminish (azaltmak) ise “designed to” amacıyla çelişir."},
  {id:"r-voc-verb-07", sub:"voc-verb", from:["vocab-02"], q:"The new data appear to ---- the hypothesis that the disease originated in bats, since the virus found in several bat colonies is almost identical to the human strain.", o:["refute","overlook","corroborate","conceal","abandon"], a:2, e:"corroborate = doğrulamak, desteklemek; virüslerin neredeyse aynı olması hipotezi destekler. refute (çürütmek) “since …” gerekçesiyle çelişir."},
  {id:"r-voc-verb-08", sub:"voc-verb", from:["vocab-02","vocab-03"], q:"Without regular maintenance, the ancient manuscripts will continue to ---- as humidity and insects damage the fragile paper.", o:["preserve","restore","enhance","protect","deteriorate"], a:4, e:"deteriorate = bozulmak, kötüleşmek; boşluktan sonra nesne olmadığı için nesne almayan bir fiil gerekir. preserve, restore ve protect hem nesne ister hem de hasar bağlamıyla çelişir."},
  {id:"r-voc-verb-09", sub:"voc-verb", from:["vocab-03"], q:"Strict import quotas were introduced to ---- domestic farmers from cheap foreign competition.", o:["expose","shield","deprive","dismiss","allege"], a:1, e:"shield somebody from = korumak; kotalar çiftçileri rekabetten korur. expose (maruz bırakmak) “to” ile kullanılır ve anlamca ters, deprive ise “of” ile kullanılır."},
  {id:"r-voc-verb-10", sub:"voc-verb", from:["w1-06"], q:"Although the minister ---- any involvement in the scandal, leaked documents later suggested that she had known about the payments from the start.", o:["confessed","admitted","acknowledged","denied","revealed"], a:3, e:"deny = inkâr etmek; although, sızan belgelerle zıtlık kuran bir fiil ister. admitted/acknowledged (kabul etmek) belgelerle çelişki yaratmaz, zıtlık kurulamaz."},
  {id:"r-voc-verb-11", sub:"voc-verb", from:["vocab-01","w1-01"], q:"Governments hoping to ---- carbon emissions have increasingly turned to taxes, which ---- companies to invest in cleaner technologies.", o:["increase / prevent","boost / discourage","sustain / forbid","raise / deter","curb / encourage"], a:4, e:"curb = dizginlemek, azaltmak; encourage somebody to do = teşvik etmek. increase/boost emisyonu artırmak anlamındadır; prevent ve deter ise “to invest” yapısıyla kullanılmaz ve anlamca terstir."},
  {id:"r-voc-verb-12", sub:"voc-verb", from:["vocab-04"], q:"Because the patient had a rare allergy, doctors had to ---- the standard treatment and use a less common alternative instead.", o:["modify","prescribe","endorse","accelerate","imitate"], a:0, e:"modify = değiştirmek, uyarlamak; alerji nedeniyle standart tedavi değiştirilir. prescribe/endorse standart tedaviyi uygulamak anlamına gelir ve “less common alternative instead” ile çelişir."},
  {id:"r-voc-verb-13", sub:"voc-verb", from:["vocab-02"], q:"Some historians ---- the fall of the Roman Republic largely to the ambitions of individual generals rather than to economic factors.", o:["accuse","blame","attribute","resemble","deny"], a:2, e:"attribute something to = bir şeyi bir nedene bağlamak. blame “on” ile (blame X on Y), accuse ise “of” ile kullanılır; edat ipucu doğru fiili belirler."},
  {id:"r-voc-verb-14", sub:"voc-verb", from:["vocab-03"], q:"The organisation's main goal is to ---- awareness of mental health issues among young people and reduce the stigma attached to them.", o:["lift","raise","emerge","rise","arise"], a:1, e:"raise awareness = farkındalık yaratmak kalıbıdır. rise ve arise nesne almaz, emerge de öyle; lift awareness ise eşdizim değildir."},
  {id:"r-voc-verb-15", sub:"voc-verb", from:["w1-06"], q:"Heavy fishing over several decades has ---- stocks of cod in the North Atlantic to a fraction of their former size.", o:["replenished","restored","enriched","depleted","multiplied"], a:3, e:"deplete = tüketmek, azaltmak; “to a fraction of their former size” büyük bir azalma gösterir. replenished/restored (yeniden doldurmak) tam tersi anlamdadır."},
  {id:"r-voc-verb-16", sub:"voc-verb", from:["vocab-03"], q:"Local authorities have been urged to ---- stricter building codes in earthquake-prone regions, as many recent collapses were caused by poor construction.", o:["enforce","relax","ignore","violate","postpone"], a:0, e:"enforce = uygulamak, yürürlüğe koymak; kötü yapılaşma yüzünden yıkılan binalar kuralların sıkı uygulanmasını gerektirir. relax (gevşetmek) “stricter” ile çelişir."},
  {id:"r-voc-verb-17", sub:"voc-verb", from:["w1-01"], q:"The discovery of penicillin ---- the treatment of bacterial infections, turning once-fatal illnesses into easily curable conditions.", o:["hindered","complicated","postponed","imitated","revolutionised"], a:4, e:"revolutionise = kökten değiştirmek; ölümcül hastalıkların kolayca tedavi edilir hâle gelmesi bunu gösterir. hindered (engellemek) ve complicated (zorlaştırmak) olumlu sonuçla çelişir."},
  {id:"r-voc-verb-18", sub:"voc-verb", from:["vocab-02"], q:"Demographers ---- that the number of people aged over 80 will triple by 2050, placing enormous pressure on healthcare systems.", o:["recall","resemble","project","withdraw","reject"], a:2, e:"project that = öngörmek, tahmin etmek; “will triple by 2050” gelecek tahminidir. recall (hatırlamak) geçmişe ilişkindir, reject/withdraw ise that-cümlesiyle anlam vermez."},
  {id:"r-voc-verb-19", sub:"voc-verb", from:["vocab-03"], q:"Students who ---- the rules on academic honesty by copying from online sources may be expelled from the university.", o:["comply","violate","obey","respect","adhere"], a:1, e:"violate = ihlal etmek; kopya çekmek kuralları çiğnemektir. comply “with”, adhere “to” ister ve anlamca terstir; obey/respect de cezayla çelişir."},
  {id:"r-voc-verb-20", sub:"voc-verb", from:["vocab-01","w1-06"], q:"The new regulations aim to ---- the entry of small firms into the market, which has long been ---- by high licensing fees.", o:["hinder / facilitated","restrict / encouraged","prevent / supported","facilitate / hindered","promote / enhanced"], a:3, e:"facilitate = kolaylaştırmak, hinder = engellemek; yüksek lisans ücretleri girişi engeller, yeni düzenleme ise kolaylaştırmayı amaçlar. promote / enhanced ilk boşluğa uysa da yüksek ücretlerin girişi “güçlendirdiği” söylenemez."},
  {id:"r-voc-verb-21", sub:"voc-verb", from:["vocab-03","w1-06"], passage:"Invasive species are organisms that have been introduced, deliberately or accidentally, into environments where they did not previously exist. Freed from the predators and diseases that kept their numbers in check at home, they often spread rapidly and (1) ---- native species for food and space. On many islands, introduced rats and cats have driven local birds to extinction, and conservationists now spend millions each year trying to remove them. Prevention, experts agree, is far cheaper than eradication.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["outcompete","coexist","emerge","nourish","protect"], a:0, e:"outcompete = rekabette alt etmek; hızla yayılan istilacı türler yerli türleri yiyecek ve alan için geride bırakır. coexist ve emerge nesne almaz, protect ise yok olma bilgisiyle çelişir."},
  {id:"r-voc-verb-22", sub:"voc-verb", from:["vocab-01"], q:"Vaccination campaigns in the twentieth century succeeded in ---- smallpox, the only human disease to have been completely wiped out.", o:["spreading","eradicating","transmitting","detecting","provoking"], a:1, e:"eradicate = kökünü kazımak; “completely wiped out” bunun eş anlamlısıdır. detecting (tespit etmek) hastalığı yok etmez, spreading/transmitting ise terstir."},
  {id:"r-voc-verb-23", sub:"voc-verb", from:["w1-06"], q:"Investors tend to ---- risky assets during periods of economic uncertainty, moving their money into safer options such as gold and government bonds.", o:["purchase","accumulate","acquire","retain","avoid"], a:4, e:"avoid = kaçınmak; paranın güvenli seçeneklere aktarılması riskli varlıklardan uzak durulduğunu gösterir. retain (elde tutmak) ve accumulate (biriktirmek) bu hareketle çelişir."},
  {id:"r-voc-verb-24", sub:"voc-verb", from:["w1-06"], q:"The judge ruled that the company had deliberately ---- information about the safety risks of its product from regulators.", o:["disclosed","revealed","withheld","reported","confirmed"], a:2, e:"withhold something from = bir şeyi birinden saklamak, vermemek; “deliberately” ve mahkeme kararı olumsuz bir eylem ister. disclosed/revealed (açıklamak) suç niteliği taşımaz."},
  {id:"r-voc-verb-25", sub:"voc-verb", from:["vocab-04"], q:"Rising temperatures are expected to ---- the melting of Arctic sea ice, which will in turn expose darker ocean water that absorbs even more heat.", o:["halt","delay","reverse","accelerate","prevent"], a:3, e:"accelerate = hızlandırmak; artan sıcaklıklar erimeyi hızlandırır ve kısır döngü oluşur. halt/delay/prevent sıcaklık artışının etkisiyle mantıksal olarak çelişir."},
  {id:"r-voc-verb-26", sub:"voc-verb", from:["vocab-02"], q:"Although the treaty was signed in 2015, several countries have yet to ---- it, so it has not come into force.", o:["ratify","violate","abolish","draft","oppose"], a:0, e:"ratify = onaylamak (meclis onayı); imzalanan antlaşma onaylanmadığı için yürürlüğe girmemiştir. draft (taslağını hazırlamak) imzadan önce yapılır, violate/abolish ise mantığa uymaz."},
  {id:"r-voc-verb-27", sub:"voc-verb", from:["w1-06","vocab-03"], q:"Small amounts of stress can actually ---- the immune system, but prolonged stress tends to weaken it.", o:["damage","suppress","undermine","impair","stimulate"], a:4, e:"stimulate = uyarmak, harekete geçirmek; but, “weaken” ile zıt bir fiil ister. damage, suppress, undermine ve impair “zayıflatmak” anlamına yakındır, zıtlığı bozar."},

  /* ---------- voc-adj ---------- */
  {id:"r-voc-adj-01", sub:"voc-adj", from:["vocab-06"], q:"Many coastal wetlands are highly ---- to rising sea levels, as they cannot migrate inland where the land has already been developed.", o:["resistant","vulnerable","immune","indifferent","beneficial"], a:1, e:"vulnerable to = -e karşı savunmasız; iç kesimlere çekilemeyen sulak alanlar risk altındadır. resistant/immune (dirençli) gerekçeyle çelişir."},
  {id:"r-voc-adj-02", sub:"voc-adj", from:["vocab-05"], q:"Although the painting was once thought to be a copy, recent analysis has provided ---- evidence that it is the work of Rembrandt himself.", o:["weak","inconclusive","vague","compelling","doubtful"], a:3, e:"compelling = ikna edici, güçlü; although eski görüşle zıt, güçlü bir kanıt ister. inconclusive/vague/weak kanıt eski görüşü değiştirmez, zıtlık kurulamaz."},
  {id:"r-voc-adj-03", sub:"voc-adj", from:["vocab-07","vocab-08"], q:"Fresh water is so ---- in parts of the Middle East that some countries rely almost entirely on desalination plants.", o:["scarce","abundant","plentiful","accessible","pure"], a:0, e:"scarce = kıt; tuzdan arındırma tesislerine bağımlılık suyun az olduğunu gösterir. abundant/plentiful (bol) “so … that” sonucu ile çelişir."},
  {id:"r-voc-adj-04", sub:"voc-adj", from:["w1-02"], q:"The bridge was declared ---- after inspectors discovered deep cracks in its supporting pillars, and it was immediately closed to all traffic.", o:["durable","robust","resilient","stable","hazardous"], a:4, e:"hazardous = tehlikeli; derin çatlaklar ve trafiğe kapatılma bunu gösterir. durable/robust/stable (sağlam) kapatılma kararıyla çelişir."},
  {id:"r-voc-adj-05", sub:"voc-adj", from:["vocab-06"], q:"The new model is ---- with older versions of the software, so users do not need to replace their existing files.", o:["incompatible","unfamiliar","compatible","inconsistent","irrelevant"], a:2, e:"compatible with = uyumlu; dosyaları değiştirmeye gerek olmaması uyumluluğu gösterir. incompatible (uyumsuz) “so …” sonucu ile çelişir."},
  {id:"r-voc-adj-06", sub:"voc-adj", from:["vocab-05"], q:"Unlike its predecessor, which was praised for its clarity, the new tax law is so ---- that even experienced accountants disagree about how it should be interpreted.", o:["explicit","ambiguous","transparent","concise","straightforward"], a:1, e:"ambiguous = belirsiz, çok anlamlı; “unlike … clarity” zıtlığı ve uzmanların yorumda anlaşamaması bunu gösterir. explicit/transparent (açık) zıtlığı bozar."},
  {id:"r-voc-adj-07", sub:"voc-adj", from:["vocab-07"], q:"Because the island's ecosystem is extremely ----, even the introduction of a single ---- species can cause lasting damage.", o:["robust / native","stable / harmless","resilient / domestic","fragile / invasive","diverse / endangered"], a:3, e:"fragile = kırılgan; invasive species = istilacı tür. Tek bir türün kalıcı zarar vermesi ekosistemin kırılgan olduğunu gösterir; robust/resilient (dayanıklı) bu sonucu açıklamaz."},
  {id:"r-voc-adj-08", sub:"voc-adj", from:["vocab-06"], q:"Online courses have made higher education ---- to millions of people who could never afford to attend a traditional university.", o:["accessible","hostile","indifferent","irrelevant","inferior"], a:0, e:"accessible to = erişilebilir; parası yetmeyen insanların eğitime ulaşması bunu gösterir. hostile to (düşmanca) ve indifferent to (kayıtsız) anlamca uymaz."},
  {id:"r-voc-adj-09", sub:"voc-adj", from:["vocab-05"], q:"The drug proved ---- in laboratory tests, but it failed to produce any significant benefit when given to human patients.", o:["useless","harmful","ineffective","toxic","promising"], a:4, e:"promising = umut verici; but, insanlarda başarısızlıkla zıt olumlu bir sıfat ister. useless/ineffective zıtlık kurmaz, harmful/toxic de “but … failed” yapısına uymaz."},
  {id:"r-voc-adj-10", sub:"voc-adj", from:["vocab-08"], q:"The ---- effects of the policy were not apparent at first; it was only a decade later that economists noticed its impact on rural employment.", o:["immediate","instant","long-term","sudden","visible"], a:2, e:"long-term = uzun vadeli; etkilerin ancak on yıl sonra fark edilmesi bunu gösterir. immediate/instant/sudden (anında) “not apparent at first” ile çelişir."},
  {id:"r-voc-adj-11", sub:"voc-adj", from:["w3-07","vocab-06"], passage:"Sleep is often regarded as a passive state, but research has shown that the brain remains remarkably active during the night. While we sleep, it sorts and stores the information gathered during the day, and it clears away waste products that build up in its tissues. For this reason, scientists now consider adequate sleep to be (1) ---- for both memory and long-term brain health, rather than a luxury that busy people can afford to sacrifice.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["harmful","essential","optional","irrelevant","secondary"], a:1, e:"essential = temel, vazgeçilmez; uykunun beyindeki işlevleri ve “rather than a luxury” zıtlığı bunu gösterir. optional/secondary tam da “luxury” anlamına yaklaşır, zıtlığı bozar."},
  {id:"r-voc-adj-12", sub:"voc-adj", from:["vocab-08"], q:"Contrary to popular belief, the Great Wall of China is not ---- from space with the naked eye, as it is far too narrow.", o:["hidden","absent","distant","visible","remote"], a:3, e:"visible = görünür; “too narrow” uzaydan görülemediğini açıklar. “not hidden” olsaydı dar olması gerekçe olmazdı."},
  {id:"r-voc-adj-13", sub:"voc-adj", from:["vocab-06"], q:"Because the region's economy is heavily ---- on a single export, a fall in global coffee prices can push thousands of families into poverty.", o:["dependent","independent","indifferent","reluctant","capable"], a:0, e:"dependent on = -e bağımlı; tek ürüne bağımlılık fiyat düşüşünün yoksulluğa yol açmasını açıklar. independent (bağımsız) sonuçla çelişir, capable “of” ister."},
  {id:"r-voc-adj-14", sub:"voc-adj", from:["vocab-06"], q:"Some bacteria have become ---- to nearly all available antibiotics, making infections caused by them extremely difficult to treat.", o:["sensitive","vulnerable","susceptible","exposed","resistant"], a:4, e:"resistant to = -e dirençli; enfeksiyonların zor tedavi edilmesi bunu gösterir. sensitive/vulnerable/susceptible (duyarlı) antibiyotiğin işe yaradığını ima eder, sonuçla çelişir."},
  {id:"r-voc-adj-15", sub:"voc-adj", from:["vocab-07"], q:"Despite being ---- in number, the rebels managed to hold the city for several months against a much larger army.", o:["superior","abundant","inferior","adequate","equal"], a:2, e:"inferior in number = sayıca az; despite, başarıyla zıt bir durum ister ve “much larger army” ipucudur. superior (üstün) zıtlık kurmaz."},
  {id:"r-voc-adj-16", sub:"voc-adj", from:["vocab-08"], q:"Climate models are becoming increasingly ----, allowing scientists to forecast regional rainfall patterns with far greater accuracy than before.", o:["crude","sophisticated","primitive","obsolete","simplistic"], a:1, e:"sophisticated = gelişmiş, karmaşık; daha doğru tahmin yapılması bunu gösterir. crude/primitive/simplistic (ilkel, kaba) doğruluktaki artışla çelişir."},
  {id:"r-voc-adj-17", sub:"voc-adj", from:["vocab-08"], q:"The ---- rise in obesity rates over the past thirty years cannot be explained by genetic factors alone, since genes do not change so quickly.", o:["slow","marginal","negligible","rapid","modest"], a:3, e:"rapid = hızlı; “genes do not change so quickly” artışın hızlı olduğunu gösterir. slow/marginal/negligible bu gerekçeyi anlamsız kılar."},
  {id:"r-voc-adj-18", sub:"voc-adj", from:["vocab-05"], q:"Critics described the report as ----, pointing out that it ignored several important studies that contradicted its conclusions.", o:["biased","balanced","impartial","objective","thorough"], a:0, e:"biased = taraflı; aykırı çalışmaları görmezden gelmek taraflılıktır. balanced/impartial/objective (tarafsız) eleştiriyle çelişir."},
  {id:"r-voc-adj-19", sub:"voc-adj", from:["vocab-05"], q:"Although the evidence linking the chemical to cancer is still ----, many experts believe it would be ---- to ban it as a precaution.", o:["conclusive / reckless","compelling / pointless","decisive / unnecessary","reliable / harmful","inconclusive / prudent"], a:4, e:"inconclusive = kesin olmayan, prudent = akıllıca, tedbirli. although: kanıt kesin değil ama önlem olarak yasaklamak akıllıca; conclusive/compelling zıtlık yaratmaz."},
  {id:"r-voc-adj-20", sub:"voc-adj", from:["vocab-07"], q:"Mobile phones, which were once ---- items owned only by the wealthy, are now used by almost everyone on the planet.", o:["common","ordinary","exclusive","cheap","widespread"], a:2, e:"exclusive = seçkin, ayrıcalıklı; “owned only by the wealthy” bunu gösterir. common/ordinary/widespread “once … now” zıtlığını bozar."},
  {id:"r-voc-adj-21", sub:"voc-adj", from:["vocab-08"], q:"The city's water supply is ---- for current needs, but officials warn that it will not be sufficient if the population continues to grow.", o:["insufficient","adequate","inadequate","scarce","limited"], a:1, e:"adequate = yeterli; but, gelecekte yetersiz kalacağı uyarısıyla zıtlık kurar. insufficient/inadequate şimdiden yetersiz demek olur, zıtlığı bozar."},
  {id:"r-voc-adj-22", sub:"voc-adj", from:["w1-02"], q:"Symptoms of the condition are often so ---- that patients do not notice them until the disease has reached an advanced stage.", o:["severe","obvious","painful","subtle","dramatic"], a:3, e:"subtle = belli belirsiz, hafif; hastaların fark etmemesi bunu gösterir. severe/obvious/dramatic belirtiler hemen fark edilirdi."},
  {id:"r-voc-adj-23", sub:"voc-adj", from:["vocab-07"], q:"It is ---- that the two scientists, working independently on different continents, published almost identical theories in the same year.", o:["remarkable","predictable","inevitable","ordinary","natural"], a:0, e:"remarkable = dikkate değer, şaşırtıcı; birbirinden habersiz iki bilim insanının aynı teoriyi yayımlaması olağan dışıdır. predictable/ordinary/natural bu tesadüfün şaşırtıcılığıyla çelişir."},
  {id:"r-voc-adj-24", sub:"voc-adj", from:["vocab-08"], q:"The museum's collection is so ---- that visitors would need several days to see all of its exhibits.", o:["modest","compact","limited","scarce","extensive"], a:4, e:"extensive = kapsamlı, geniş; birkaç gün gerekmesi bunu gösterir. modest/limited/compact (küçük, sınırlı) “so … that” sonucu ile çelişir."},
  {id:"r-voc-adj-25", sub:"voc-adj", from:["w3-07"], passage:"For centuries, the Silk Road connected China with the Mediterranean world. Merchants carried silk, spices and precious metals along its many routes, but the trade was never easy. Travellers faced deserts, mountain passes and bandits, and a single journey could take several years. Because the risks were so (1) ----, few merchants travelled the entire route; instead, goods passed through the hands of many traders, each covering only a short section.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["negligible","minor","considerable","trivial","manageable"], a:2, e:"considerable = önemli, büyük; çöller, haydutlar ve yıllar süren yolculuk risklerin büyük olduğunu gösterir. negligible/minor/trivial (önemsiz) “few merchants travelled the entire route” sonucunu açıklamaz."},
  {id:"r-voc-adj-26", sub:"voc-adj", from:["vocab-08"], q:"Solar power was once considered too ---- to compete with fossil fuels, but its cost has fallen by almost 90 percent in the last decade.", o:["cheap","costly","efficient","affordable","profitable"], a:1, e:"costly = pahalı; “too … to compete” ve maliyetin düşmesi bunu gösterir. cheap/affordable (ucuz) rekabet edememeyi açıklamaz."},
  {id:"r-voc-adj-27", sub:"voc-adj", from:["vocab-07"], q:"Many ancient cities were built near rivers, as the surrounding land was ---- and could support large populations through agriculture.", o:["barren","arid","hostile","remote","fertile"], a:4, e:"fertile = verimli; tarımla büyük nüfusu beslemek bunu gösterir. barren (çorak) ve arid (kurak) tarımsal verimlilikle çelişir."},

  /* ---------- voc-adv ---------- */
  {id:"r-voc-adv-01", sub:"voc-adv", from:["vocab-09"], q:"The price of solar panels has fallen ---- over the past decade, making renewable energy cheaper than coal in many countries.", o:["slightly","barely","dramatically","hardly","scarcely"], a:2, e:"dramatically = çarpıcı biçimde; kömürden ucuz hâle gelmek büyük bir düşüş gerektirir. barely/hardly/scarcely “neredeyse hiç” anlamı taşır, slightly (biraz) ise sonucu açıklamaz."},
  {id:"r-voc-adv-02", sub:"voc-adv", from:["vocab-11"], q:"The results of the two surveys were ---- identical, differing by less than one percent on every question.", o:["virtually","hardly","rarely","seldom","partly"], a:0, e:"virtually = neredeyse, hemen hemen; yüzde birden az fark bunu gösterir. hardly identical “hiç de aynı değil” anlamı verir, rarely/seldom sıklık zarfıdır."},
  {id:"r-voc-adv-03", sub:"voc-adv", from:["vocab-10"], q:"The medicine should be taken ---- as prescribed, since even a small change in the dose can cause serious side effects.", o:["occasionally","roughly","approximately","loosely","precisely"], a:4, e:"precisely = tam olarak; küçük bir doz değişikliğinin bile zararlı olması kesinlik ister. roughly/approximately (yaklaşık) bu uyarıyla çelişir."},
  {id:"r-voc-adv-04", sub:"voc-adv", from:["w1-03"], q:"The fire was started ----; investigators found traces of petrol at three different points in the building.", o:["accidentally","deliberately","naturally","spontaneously","reluctantly"], a:1, e:"deliberately = kasten; üç farklı noktada benzin izi bulunması yangının bilerek çıkarıldığını gösterir. accidentally (kazara) bu kanıtla çelişir."},
  {id:"r-voc-adv-05", sub:"voc-adv", from:["vocab-12"], q:"Voter turnout in local elections is ---- low; in most districts fewer than one in three eligible citizens cast a ballot.", o:["rarely","hardly","seldom","notoriously","barely"], a:3, e:"notoriously = herkesçe bilindiği üzere (olumsuz); üçte birin altındaki katılım bunu destekler. hardly/barely low “pek düşük değil” anlamı verir ve rakamla çelişir."},
  {id:"r-voc-adv-06", sub:"voc-adv", from:["vocab-09"], q:"The company's profits rose only ---- last year, as higher sales were largely offset by rising costs.", o:["marginally","sharply","considerably","dramatically","substantially"], a:0, e:"marginally = çok az; “only” ve artan maliyetlerin satışları dengelemesi küçük bir artış gösterir. sharply/considerably “only” ile çelişir."},
  {id:"r-voc-adv-07", sub:"voc-adv", from:["vocab-10"], q:"Although the manager ---- agreed to the proposal, she made it clear that she still had serious doubts about it.", o:["eagerly","enthusiastically","reluctantly","wholeheartedly","readily"], a:2, e:"reluctantly = isteksizce; ciddi şüpheler isteksiz bir onayı gösterir. eagerly/enthusiastically (hevesle) şüphelerle bağdaşmaz; although burada kabul ile şüphe arasındaki zıtlığı kurar."},
  {id:"r-voc-adv-08", sub:"voc-adv", from:["vocab-10","vocab-12"], q:"Hurricanes in the region ---- occur between June and November; storms outside this period are ---- recorded.", o:["rarely / frequently","seldom / often","occasionally / always","hardly / commonly","typically / rarely"], a:4, e:"typically = genellikle, rarely = nadiren; fırtınaların belirli dönemde yoğunlaşması, dönem dışında nadir görüldüğü anlamına gelir. seldom / often ise tam tersi bir tablo çizer."},
  {id:"r-voc-adv-09", sub:"voc-adv", from:["vocab-10"], q:"The disease is spread ---- through contaminated water, which is why improving sanitation has been so effective in controlling it.", o:["rarely","primarily","hardly","barely","seldom"], a:1, e:"primarily = başlıca, esas olarak; “which is why” sanitasyonun etkili olmasını ana bulaş yoluyla açıklar. rarely/seldom bu sonucu açıklamaz."},
  {id:"r-voc-adv-10", sub:"voc-adv", from:["vocab-11"], q:"The theory was ---- rejected by the scientific community when it was first proposed, and it took decades for it to gain acceptance.", o:["warmly","eagerly","enthusiastically","widely","favourably"], a:3, e:"widely = geniş çapta, yaygın olarak; kabul görmenin on yıllar sürmesi bunu gösterir. warmly/favourably olumlu tutum zarflarıdır, “rejected” ile çelişir."},
  {id:"r-voc-adv-11", sub:"voc-adv", from:["vocab-11"], q:"The new law applies ---- to companies with more than 250 employees; smaller firms are exempt.", o:["exclusively","equally","universally","generally","widely"], a:0, e:"exclusively = yalnızca; küçük firmaların muaf olması bunu gösterir. equally/universally (herkese eşit) muafiyetle çelişir."},
  {id:"r-voc-adv-12", sub:"voc-adv", from:["vocab-12","vocab-10"], q:"Children who read regularly ---- perform better in language tests, although reading alone does not guarantee success.", o:["invariably","never","generally","hardly","seldom"], a:2, e:"generally = genellikle; “does not guarantee success” istisnalar olduğunu söyler. invariably (istisnasız) bu kısıtlamayla çelişir, hardly/seldom ise olumlu eğilimi ters çevirir."},
  {id:"r-voc-adv-13", sub:"voc-adv", from:["w1-03"], q:"The painting had been ---- restored in the nineteenth century, so experts had to remove several layers of later paint to reveal the original colours.", o:["skilfully","faithfully","carefully","accurately","poorly"], a:4, e:"poorly = kötü, özensiz; sonradan eklenen boya katmanlarının temizlenmesi gerekmesi eski restorasyonun başarısız olduğunu gösterir. skilfully/faithfully bu sonucu açıklamaz."},
  {id:"r-voc-adv-14", sub:"voc-adv", from:["w1-03","vocab-11"], q:"Although the two languages share many words, they are ---- unrelated, belonging to entirely different language families.", o:["superficially","genetically","visually","partially","temporarily"], a:1, e:"genetically = köken bakımından; farklı dil ailelerine ait olmak kökende akraba olmamaktır. superficially (yüzeysel olarak) ortak kelimelere gönderme yapar ve although zıtlığını bozar."},
  {id:"r-voc-adv-15", sub:"voc-adv", from:["w1-03"], q:"The bridge will be ---- closed during repairs, but it is expected to reopen to traffic in early spring.", o:["permanently","eternally","formerly","temporarily","previously"], a:3, e:"temporarily = geçici olarak; ilkbaharda yeniden açılacak olması bunu gösterir. permanently (kalıcı olarak) “reopen” ile çelişir."},
  {id:"r-voc-adv-16", sub:"voc-adv", from:["vocab-10"], q:"The effects of the new drug are ---- understood, so doctors are cautious about prescribing it to pregnant women.", o:["poorly","fully","thoroughly","widely","completely"], a:0, e:"poorly understood = yeterince anlaşılmamış; doktorların temkinli olması bunu gösterir. fully/thoroughly (tamamen) temkinliliği açıklamaz."},
  {id:"r-voc-adv-17", sub:"voc-adv", from:["vocab-09"], passage:"Honeybees are among the most important pollinators on the planet. Around a third of the food crops that humans eat depend, at least in part, on insect pollination. In recent years, however, bee populations in North America and Europe have declined (1) ----, with some beekeepers losing more than half of their colonies in a single winter. Scientists believe that pesticides, parasites and habitat loss are all to blame, and many are calling for urgent action.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["barely","slightly","sharply","hardly","marginally"], a:2, e:"sharply = keskin biçimde; tek kışta kolonilerin yarısından fazlasının kaybı büyük düşüştür. slightly/marginally (biraz) bu oranla, barely/hardly ise “düşüş” fikriyle çelişir."},
  {id:"r-voc-adv-18", sub:"voc-adv", from:["w1-03","vocab-10"], q:"Participants were ---- assigned to one of two groups, so that neither the researchers nor the volunteers could influence who received the real drug.", o:["deliberately","carefully","intentionally","selectively","randomly"], a:4, e:"randomly = rastgele; kimsenin grupları etkileyememesi rastgele atamayı gösterir. deliberately/selectively (kasıtlı, seçerek) “so that neither … could influence” ile çelişir."},
  {id:"r-voc-adv-19", sub:"voc-adv", from:["vocab-11"], q:"The island is ---- accessible by boat; there is no airport, and the only bridge was destroyed decades ago.", o:["hardly","only","seldom","partly","frequently"], a:1, e:"only = yalnızca; havalimanı ve köprü olmaması tek ulaşım yolunun tekne olduğunu gösterir. hardly accessible “teknelerle bile zor ulaşılır” anlamı verir ve açıklamayla uyuşmaz."},
  {id:"r-voc-adv-20", sub:"voc-adv", from:["vocab-12"], q:"Scientists have ---- warned that the country's groundwater reserves are being used faster than they can be replenished, but their warnings have largely been ignored.", o:["seldom","never","hardly","repeatedly","rarely"], a:3, e:"repeatedly = defalarca; “their warnings have largely been ignored” çok sayıda uyarı yapıldığını varsayar. never/seldom/rarely uyarıların varlığıyla çelişir."},
  {id:"r-voc-adv-21", sub:"voc-adv", from:["vocab-09","vocab-11"], q:"Unemployment fell ---- in the first quarter, dropping from 9 to 5 percent, but it has ---- changed since then, remaining at around 5 percent.", o:["sharply / barely","slightly / considerably","hardly / dramatically","gradually / greatly","marginally / substantially"], a:0, e:"sharply = keskin biçimde (%9'dan %5'e), barely changed = neredeyse hiç değişmedi (%5 civarında kaldı). slightly / considerably rakamlarla tam ters düşer."},
  {id:"r-voc-adv-22", sub:"voc-adv", from:["vocab-09"], q:"The ancient manuscript was ---- preserved, with almost every page still perfectly legible after nearly a thousand years.", o:["badly","poorly","remarkably","partly","barely"], a:2, e:"remarkably preserved = dikkat çekici derecede iyi korunmuş; sayfaların okunaklı olması bunu gösterir. badly/poorly/barely bu bilgiyle çelişir."},
  {id:"r-voc-adv-23", sub:"voc-adv", from:["vocab-10"], q:"Contrary to what many people assume, the brain's ability to form new connections does not stop in adulthood; it continues ---- throughout life.", o:["briefly","temporarily","rarely","formerly","steadily"], a:4, e:"steadily = sürekli, istikrarlı biçimde; “throughout life” ve “does not stop” bunu destekler. briefly/temporarily (kısa süreli) “throughout life” ile çelişir."},
  {id:"r-voc-adv-24", sub:"voc-adv", from:["vocab-11"], q:"Most of the town's residents are employed ---- or indirectly by the car factory, so its closure would devastate the local economy.", o:["slightly","directly","hardly","formerly","rarely"], a:1, e:"directly or indirectly = doğrudan ya da dolaylı olarak; “or indirectly” ile eşleşen zarf directly'dir. hardly/rarely olumsuz anlam verir ve kapanmanın yıkıcı etkisini açıklamaz."},
  {id:"r-voc-adv-25", sub:"voc-adv", from:["vocab-09"], q:"The decision to raise interest rates was ---- controversial, with half of the committee members voting against it.", o:["hardly","scarcely","barely","highly","rarely"], a:3, e:"highly controversial = son derece tartışmalı; üyelerin yarısının karşı oy vermesi bunu gösterir. hardly/scarcely/barely “pek tartışmalı değil” anlamı verir."},
  {id:"r-voc-adv-26", sub:"voc-adv", from:["w1-03"], q:"Although the storm was ---- expected to hit the capital, it changed direction at the last minute and struck a small coastal town instead.", o:["initially","eventually","finally","subsequently","afterwards"], a:0, e:"initially = başlangıçta; son dakikada yön değiştirme ilk beklentiyle zıtlık kurar. eventually/finally (sonunda) although zıtlığını ve zaman sırasını bozar."},
  {id:"r-voc-adv-27", sub:"voc-adv", from:["vocab-09"], q:"Cases of the disease have ---- increased since vaccination rates began to fall, rising from a few hundred to over twenty thousand in five years.", o:["barely","slightly","hardly","marginally","substantially"], a:4, e:"substantially = önemli ölçüde; birkaç yüzden yirmi binin üzerine çıkış çok büyük bir artıştır. slightly/marginally (biraz) ve barely/hardly (neredeyse hiç) bu rakamla çelişir."},

  /* ---------- voc-noun ---------- */
  {id:"r-voc-noun-01", sub:"voc-noun", from:["vocab-16"], q:"Plastic waste in the oceans poses a serious ---- to marine life, as many animals mistake it for food and die as a result.", o:["benefit","solution","remedy","threat","relief"], a:3, e:"pose a threat to = tehdit oluşturmak kalıbıdır. benefit/relief olumlu anlamlıdır, hayvanların ölmesiyle çelişir; solution ve remedy “pose … to” ile kullanılmaz."},
  {id:"r-voc-noun-02", sub:"voc-noun", from:["w1-04"], q:"The rapid ---- of mobile banking in Kenya has allowed millions of people without bank accounts to send and receive money.", o:["spread","decline","collapse","absence","shortage"], a:0, e:"spread = yayılma; milyonların hizmete erişmesi yaygınlaşmayı gösterir. decline/collapse (düşüş, çöküş) bu olumlu sonuçla çelişir."},
  {id:"r-voc-noun-03", sub:"voc-noun", from:["vocab-15"], q:"The proposed dam has come under close ---- from environmental groups, who fear it will destroy the habitats of several endangered species.", o:["approval","praise","scrutiny","support","applause"], a:2, e:"come under scrutiny = mercek altına alınmak kalıbıdır; çevrecilerin endişesi olumsuz bir tepki ister. approval/praise/support endişeyle çelişir."},
  {id:"r-voc-noun-04", sub:"voc-noun", from:["vocab-16"], q:"Researchers found a strong ---- between air pollution and the number of hospital admissions for asthma.", o:["difference","distinction","gap","contrast","correlation"], a:4, e:"correlation between = arasında ilişki, bağıntı; hava kirliliği ile astım başvuruları arasındaki bağlantı kastedilir. difference/contrast karşıtlık bildirir ve “strong” ile bu bağlamda anlamlı değildir."},
  {id:"r-voc-noun-05", sub:"voc-noun", from:["vocab-13"], q:"The main ---- of the study is that it relied on data from a single hospital, so its findings may not apply to other populations.", o:["strength","limitation","advantage","merit","benefit"], a:1, e:"limitation = sınırlılık, zayıf yön; tek hastane verisi bulguların genellenmesini engeller. strength/advantage/merit olumlu anlamlıdır, “may not apply” ile çelişir."},
  {id:"r-voc-noun-06", sub:"voc-noun", from:["vocab-14","vocab-15"], q:"Despite years of talks, the two countries have failed to reach any ---- over the disputed border, and the issue remains a major source of ---- between them.", o:["conflict / harmony","dispute / cooperation","controversy / agreement","agreement / tension","consensus / relief"], a:3, e:"reach an agreement = anlaşmaya varmak; source of tension = gerginlik kaynağı. consensus ilk boşluğa uysa da “source of relief between them” anlamsızdır; conflict/dispute “reach” ile anlaşma anlamı vermez."},
  {id:"r-voc-noun-07", sub:"voc-noun", from:["vocab-16"], q:"Smoking remains the leading ---- of preventable death in many countries, responsible for millions of deaths each year.", o:["cause","cure","result","remedy","effect"], a:0, e:"the leading cause of = başlıca nedeni; “responsible for millions of deaths” nedenselliği gösterir. result/effect sonuç bildirir, cure/remedy ise tedavi anlamındadır."},
  {id:"r-voc-noun-08", sub:"voc-noun", from:["vocab-13"], q:"The government introduced tax ---- to encourage companies to invest in research and development.", o:["penalties","burdens","incentives","obstacles","fines"], a:2, e:"tax incentives = vergi teşvikleri; “to encourage” amacı bunu gerektirir. penalties/fines/burdens (ceza, yük) teşvik amacıyla çelişir."},
  {id:"r-voc-noun-09", sub:"voc-noun", from:["w1-04"], q:"The ---- of the Internet in the 1990s transformed the way people communicated, shopped and obtained information.", o:["collapse","decline","disappearance","abolition","advent"], a:4, e:"advent = ortaya çıkış, gelişi; internetin 1990'larda gelmesi hayatı dönüştürmüştür. collapse/decline/disappearance bu dönüşümü açıklamaz."},
  {id:"r-voc-noun-10", sub:"voc-noun", from:["vocab-13"], q:"Many young people can no longer afford to buy a home, as rising prices have put property out of their ----.", o:["range","reach","sight","mind","order"], a:1, e:"out of (one's) reach = ulaşılamaz, erişim dışında kalıbıdır. out of sight/mind “göz önünden, akıldan uzak” anlamındadır; fiyatlarla ilgili değildir."},
  {id:"r-voc-noun-11", sub:"voc-noun", from:["vocab-16"], q:"The new vaccine has shown a high level of ---- in clinical trials, preventing infection in 95 percent of participants.", o:["toxicity","failure","resistance","efficacy","deficiency"], a:3, e:"efficacy = etkinlik; %95 koruma yüksek etkinliktir. toxicity (zehirlilik) ve failure (başarısızlık) bu olumlu sonuçla çelişir."},
  {id:"r-voc-noun-12", sub:"voc-noun", from:["vocab-15"], q:"The factory was fined for its repeated ---- of safety regulations, which had put workers' lives at risk.", o:["violation","compliance","observance","enforcement","approval"], a:0, e:"violation = ihlal; para cezası ve işçilerin hayatının riske girmesi kuralların çiğnendiğini gösterir. compliance/observance (uyma) cezayla çelişir."},
  {id:"r-voc-noun-13", sub:"voc-noun", from:["vocab-13"], passage:"In many developing countries, a large share of the population works in the informal economy, selling goods on the street or doing casual work without a formal contract. Such workers usually have no access to pensions, sick pay or unemployment benefits. As a result, even a short illness can place a heavy (1) ---- on a family's finances, forcing parents to borrow money or take their children out of school. Extending social protection to these workers remains a major challenge for governments.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["reward","relief","burden","profit","surplus"], a:2, e:"place a heavy burden on = ağır bir yük bindirmek; borç alma ve çocukları okuldan alma sonuçları bunu gösterir. relief/reward/profit olumlu anlamlıdır, “heavy … on” kalıbına uymaz."},
  {id:"r-voc-noun-14", sub:"voc-noun", from:["vocab-14"], q:"There is growing ---- among scientists that the loss of biodiversity could threaten global food security.", o:["relief","satisfaction","confidence","indifference","concern"], a:4, e:"concern = endişe; “could threaten” olumsuz bir olasılık bildirir. relief/satisfaction olumlu duygulardır, indifference (kayıtsızlık) ise “growing” ve tehdit bilgisiyle uyuşmaz."},
  {id:"r-voc-noun-15", sub:"voc-noun", from:["vocab-16"], q:"The ---- of the population living in cities has risen from about 30 percent in 1950 to more than half today.", o:["amount","proportion","number","quantity","size"], a:1, e:"proportion = oran; yüzde ve “more than half” oran bildirir. amount/quantity sayılamayan miktar içindir, number ise yüzdeyle ifade edilmez."},
  {id:"r-voc-noun-16", sub:"voc-noun", from:["w1-04"], q:"The discovery of oil off the coast led to a sudden ---- in the town's population, as workers arrived from all over the country.", o:["decline","drop","shortage","surge","loss"], a:3, e:"surge = ani artış; ülkenin her yerinden işçi gelmesi nüfusun arttığını gösterir. decline/drop/loss (azalma) bu bilgiyle çelişir."},
  {id:"r-voc-noun-17", sub:"voc-noun", from:["vocab-13"], q:"The researchers took every ---- to ensure that the samples were not contaminated, wearing protective suits and sterilising all equipment.", o:["precaution","risk","threat","mistake","damage"], a:0, e:"take every precaution = her türlü önlemi almak kalıbıdır. take a risk “risk almak” demektir ve koruyucu önlemlerle çelişir."},
  {id:"r-voc-noun-18", sub:"voc-noun", from:["vocab-13","vocab-16"], q:"Critics argue that the new law will have a negative ---- on freedom of the press, since journalists may be prosecuted for revealing official secrets.", o:["effort","attempt","impact","attitude","approach"], a:2, e:"have an impact on = etkisi olmak kalıbıdır. effort/attempt (çaba) ve approach (yaklaşım) “have a negative … on” yapısıyla eşdizim oluşturmaz."},
  {id:"r-voc-noun-19", sub:"voc-noun", from:["vocab-15"], q:"The government's decision to close rural schools has met with fierce ---- from parents, who say their children will have to travel for hours each day.", o:["support","approval","enthusiasm","gratitude","opposition"], a:4, e:"meet with fierce opposition = şiddetli muhalefetle karşılaşmak; velilerin şikâyeti olumsuz tepki ister. support/approval/gratitude “fierce” ve şikâyetle çelişir."},
  {id:"r-voc-noun-20", sub:"voc-noun", from:["vocab-14"], q:"Although scientists broadly agree on the ---- of climate change, there is still considerable ---- about how quickly sea levels will rise.", o:["doubt / certainty","causes / uncertainty","cures / consensus","denial / agreement","benefits / confidence"], a:1, e:"causes = nedenler, uncertainty = belirsizlik; although genel uzlaşı ile belirsizlik arasında zıtlık kurar. cures / consensus zıtlık yaratmaz, çünkü ikinci kısım da uzlaşı bildirir."},
  {id:"r-voc-noun-21", sub:"voc-noun", from:["vocab-16"], q:"Lack of sleep can impair a person's ---- to concentrate, making mistakes at work or on the road more likely.", o:["failure","reluctance","refusal","ability","tendency"], a:3, e:"ability to concentrate = konsantre olma yeteneği; uykusuzluk bu yeteneği bozar (impair). failure/reluctance/refusal zaten olumsuzdur, “impair” ile anlamsız olur."},
  {id:"r-voc-noun-22", sub:"voc-noun", from:["w1-04"], q:"The ---- of new farming techniques during the eighteenth century greatly increased food production in Britain.", o:["adoption","rejection","abandonment","prohibition","neglect"], a:0, e:"adoption = benimsenme, uygulamaya konma; üretimin artması yeni tekniklerin kullanıldığını gösterir. rejection/abandonment/prohibition bu sonuçla çelişir."},
  {id:"r-voc-noun-23", sub:"voc-noun", from:["vocab-15"], q:"Despite repeated warnings, the city failed to take any ---- to strengthen its flood defences, and the storm caused enormous damage.", o:["attention","notice","action","part","place"], a:2, e:"take action to do = harekete geçmek kalıbıdır. take part (katılmak) ve take place (gerçekleşmek) anlamca uymaz; take notice “to strengthen” ile kullanılmaz."},
  {id:"r-voc-noun-24", sub:"voc-noun", from:["w1-04"], passage:"The Black Death, which swept across Europe between 1347 and 1351, killed perhaps a third of the continent's population. Its long-term consequences were surprising. With so many workers dead, labour became scarce, and surviving peasants were able to demand higher wages and better conditions. In this way, a demographic catastrophe contributed to the gradual (1) ---- of the feudal system, which had depended on a large supply of cheap labour.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["emergence","establishment","expansion","strengthening","decline"], a:4, e:"decline = gerileme, çöküş; ucuz işgücüne dayanan feodal sistem işgücü kıtlığıyla zayıflamıştır. emergence/establishment/strengthening bu mantıkla çelişir."},
  {id:"r-voc-noun-25", sub:"voc-noun", from:["vocab-13"], q:"Many elderly people live in ---- and have few opportunities for social contact, which can seriously affect their mental health.", o:["luxury","isolation","harmony","comfort","prosperity"], a:1, e:"isolation = yalnızlık, yalıtılmışlık; az sosyal temas ve ruh sağlığına olumsuz etki bunu gösterir. luxury/comfort/prosperity olumlu anlamlıdır, bağlamla çelişir."},
  {id:"r-voc-noun-26", sub:"voc-noun", from:["vocab-14"], q:"The ---- of the experiment could not be repeated by other laboratories, which cast doubt on the original claims.", o:["causes","objections","criticisms","findings","doubts"], a:3, e:"findings = bulgular; bilimde tekrarlanabilirlik bulgular için söz konusudur ve tekrarlanamaması iddialara şüphe düşürür. objections/criticisms/doubts “tekrarlanmak” ile anlam vermez."},
  {id:"r-voc-noun-27", sub:"voc-noun", from:["vocab-16","vocab-13"], q:"Obesity has become a major public health ---- in many wealthy countries, with rates having nearly tripled since 1975.", o:["concern","achievement","success","solution","remedy"], a:0, e:"public health concern = halk sağlığı sorunu; oranların üç katına çıkması olumsuz bir durumdur. achievement/success/solution olumlu anlamlıdır, bağlamla çelişir."},

  /* ---------- voc-phrasal ---------- */
  {id:"r-voc-phrasal-01", sub:"voc-phrasal", from:["vocab-17","w1-05"], q:"A team of engineers was sent to ---- the cause of the power failure that left half the city without electricity.", o:["put off","call off","give up","make up for","look into"], a:4, e:"look into = araştırmak, incelemek (investigate); “the cause of” araştırılacak bir şeydir. put off (ertelemek) ve call off (iptal etmek) mühendislerin gönderilme amacına uymaz."},
  {id:"r-voc-phrasal-02", sub:"voc-phrasal", from:["w1-05"], q:"Several airlines were forced to ---- hundreds of flights after volcanic ash made it unsafe to fly over northern Europe.", o:["carry out","call off","take off","set up","bring about"], a:1, e:"call off = iptal etmek; uçuşun güvensiz hâle gelmesi iptali gerektirir. carry out (gerçekleştirmek) “forced to” ve güvensizlikle çelişir; take off (havalanmak) nesne almaz."},
  {id:"r-voc-phrasal-03", sub:"voc-phrasal", from:["vocab-18"], q:"After losing two key players to injury, the team struggled to ---- their absence and lost the next three matches.", o:["account for","look into","carry out","make up for","put off"], a:3, e:"make up for = telafi etmek, eksikliğini gidermek; sakat oyuncuların yokluğu telafi edilmeye çalışılır. account for “açıklamak/oluşturmak” demektir, telafi anlamı taşımaz."},
  {id:"r-voc-phrasal-04", sub:"voc-phrasal", from:["vocab-17"], q:"The government plans to ---- a special committee to investigate allegations of corruption within the police force.", o:["set up","break down","put up with","run out of","get over"], a:0, e:"set up = kurmak (establish); komisyon kurulur. break down (çökmek) nesne almaz, put up with (katlanmak) anlamca uymaz."},
  {id:"r-voc-phrasal-05", sub:"voc-phrasal", from:["vocab-19"], q:"Residents living near the airport have had to ---- constant noise for years, and many are now demanding compensation.", o:["look after","account for","put up with","bring about","carry out"], a:2, e:"put up with = katlanmak (tolerate); yıllarca gürültüye katlanan sakinler tazminat ister. bring about (neden olmak) sakinlerin eylemi olamaz."},
  {id:"r-voc-phrasal-06", sub:"voc-phrasal", from:["vocab-20"], q:"The use of smartphones ---- quickly among teenagers, and within a few years almost every student owned one.", o:["broke down","called off","put off","gave up","caught on"], a:4, e:"catch on = tutmak, yaygınlaşmak; neredeyse her öğrencinin telefon sahibi olması bunu gösterir. broke down (çöktü) ve gave up (vazgeçti) bu sonuçla çelişir."},
  {id:"r-voc-phrasal-07", sub:"voc-phrasal", from:["vocab-18"], q:"Women ---- nearly 60 percent of university graduates in the country, yet they hold fewer than a fifth of senior management positions.", o:["make up for","account for","look after","run out of","bring about"], a:1, e:"account for = (bir oranı) oluşturmak; mezunların %60'ı kadındır. make up for “telafi etmek” anlamındadır, oranla kullanılmaz — sık karıştırılan tuzaktır."},
  {id:"r-voc-phrasal-08", sub:"voc-phrasal", from:["w1-05","vocab-17"], q:"The meeting was ---- until next month because the chairman was ill, and some members fear the project may eventually be ---- altogether.", o:["carried out / set up","called off / brought about","looked into / accounted for","put off / called off","set up / carried out"], a:3, e:"put off = ertelemek (“until next month”), call off = iptal etmek (“altogether”). called off “until next month” ile kullanılmaz, çünkü iptal edilen bir şey belirli bir tarihe ertelenmez."},
  {id:"r-voc-phrasal-09", sub:"voc-phrasal", from:["vocab-18"], q:"If current consumption rates continue, some regions could ---- groundwater within the next few decades.", o:["run out of","make up for","come across","look into","put up with"], a:0, e:"run out of = tükenmek, bitirmek; mevcut tüketim hızı yeraltı suyunun tükenmesine yol açar. make up for (telafi etmek) ve come across (rastlamak) anlamca uymaz."},
  {id:"r-voc-phrasal-10", sub:"voc-phrasal", from:["vocab-19"], q:"While sorting through old documents in the archive, a historian ---- a letter that shed new light on the causes of the war.", o:["put off","called off","came across","carried out","set up"], a:2, e:"come across = tesadüfen rastlamak (encounter); belgeleri karıştırırken bir mektup bulunur. carried out (yürütmek) ve set up (kurmak) mektupla anlam oluşturmaz."},
  {id:"r-voc-phrasal-11", sub:"voc-phrasal", from:["vocab-19"], q:"It took the region years to ---- the effects of the earthquake, which destroyed thousands of homes and much of its infrastructure.", o:["bring about","carry out","set up","call off","get over"], a:4, e:"get over = atlatmak, üstesinden gelmek (recover from); bölge depremin etkilerini yıllar içinde atlatır. bring about (neden olmak) depremin etkilerine bölgenin neden olduğunu söyler, mantıksızdır."},
  {id:"r-voc-phrasal-12", sub:"voc-phrasal", from:["vocab-19"], q:"Experts believe that the economic crisis was ---- by a combination of reckless lending and weak regulation.", o:["looked into","brought about","put up with","come across","made up for"], a:1, e:"bring about = neden olmak (cause); kriz bir dizi etkenin sonucudur. looked into “incelenmek” anlamı verir, ama “by a combination of reckless lending” inceleyen değil neden bildirir."},
  {id:"r-voc-phrasal-13", sub:"voc-phrasal", from:["w1-05"], q:"Many people ---- smoking after the government introduced large warning images on cigarette packets.", o:["took up","set up","carried out","gave up","brought about"], a:3, e:"give up = bırakmak, vazgeçmek; uyarı görsellerinin amacı sigarayı bıraktırmaktır. took up (başlamak) bu bağlamla çelişir."},
  {id:"r-voc-phrasal-14", sub:"voc-phrasal", from:["vocab-17"], passage:"In 1928, Alexander Fleming returned from holiday to find that a mould had contaminated one of his bacterial cultures. Around the mould, the bacteria had been destroyed. Rather than throwing the dish away, Fleming decided to (1) ---- the matter further. His curiosity eventually led to the discovery of penicillin, although it was more than a decade before other scientists found a way to produce the drug in large quantities.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["look into","put off","give up","call off","run out of"], a:0, e:"look into = araştırmak; “rather than throwing the dish away” ve “his curiosity” konunun incelendiğini gösterir. give up ve put off merakla ve keşifle çelişir."},
  {id:"r-voc-phrasal-15", sub:"voc-phrasal", from:["w1-05"], q:"Despite the heavy rain, rescue teams ---- searching for survivors throughout the night.", o:["gave up","called off","carried on","put off","broke down"], a:2, e:"carry on doing = devam etmek; despite, yağmura rağmen aramanın sürdüğünü gösterir. gave up (vazgeçti) despite zıtlığını bozar."},
  {id:"r-voc-phrasal-16", sub:"voc-phrasal", from:["vocab-17"], q:"The charity was ---- in 1998 to provide clean water to villages in East Africa.", o:["broken down","put off","called off","turned down","set up"], a:4, e:"set up = kurmak (establish); bir hayır kurumu belirli bir yılda kurulur. called off (iptal edilmek) ve turned down (reddedilmek) “to provide clean water” amacıyla uyuşmaz."},
  {id:"r-voc-phrasal-17", sub:"voc-phrasal", from:["vocab-17"], q:"The minister ---- the invitation to attend the summit, saying that she had more pressing matters to deal with at home.", o:["carried out","turned down","brought about","looked after","set up"], a:1, e:"turn down = reddetmek (reject); daha acil işleri olduğunu söylemesi daveti reddettiğini gösterir. carried out ve set up “invitation” ile anlamlı değildir."},
  {id:"r-voc-phrasal-18", sub:"voc-phrasal", from:["vocab-20"], q:"Several species of frog have ---- in the last thirty years, largely as a result of a fungal disease that has spread across the tropics.", o:["set up","taken off","broken down","died out","carried out"], a:3, e:"die out = nesli tükenmek; mantar hastalığı türlerin yok olmasına yol açar. taken off (hızla yükselmek) olumlu anlamlıdır, broken down ise canlılar için kullanılmaz."},
  {id:"r-voc-phrasal-19", sub:"voc-phrasal", from:["vocab-20"], q:"Sales of electric vehicles have ---- in recent years, rising from a few thousand to several million a year.", o:["taken off","died out","broken down","called off","fallen behind"], a:0, e:"take off = hızla yükselmek, patlama yapmak; birkaç binden milyonlara çıkış bunu gösterir. died out ve fallen behind (geride kalmak) artışla çelişir."},
  {id:"r-voc-phrasal-20", sub:"voc-phrasal", from:["vocab-17","vocab-18"], q:"Researchers ---- a series of experiments to test the theory, but the results failed to ---- the unusual patterns observed in the original data.", o:["put off / look into","called off / bring about","carried out / account for","gave up / make up for","set up / come across"], a:2, e:"carry out experiments = deney yapmak; account for = açıklamak. set up ilk boşluğa uysa da “come across the patterns” (desenlere rastlamak) “failed to … observed patterns” ile anlamsızdır."},
  {id:"r-voc-phrasal-21", sub:"voc-phrasal", from:["vocab-20"], q:"The old washing machine finally ---- after twenty years of use, and the family had to buy a new one.", o:["took off","caught on","set up","went through","broke down"], a:4, e:"break down = (makine) bozulmak; yeni makine alınması bunu gösterir. took off ve caught on olumlu anlamlıdır, went through (gerçekleşmek, onaylanmak) makine için uymaz."},
  {id:"r-voc-phrasal-22", sub:"voc-phrasal", from:["vocab-19"], q:"Parents who work long hours often rely on grandparents to ---- their children during the day.", o:["look into","look after","look up to","look forward to","look down on"], a:1, e:"look after = bakmak, ilgilenmek (take care of). look into (araştırmak), look up to (saygı duymak) ve look down on (küçümsemek) aynı fiille kurulan çeldiricilerdir."},
  {id:"r-voc-phrasal-23", sub:"voc-phrasal", from:["vocab-17"], q:"The spokesperson was asked to ---- the details of the new policy, since many people had found the original announcement confusing.", o:["turn down","call off","put off","spell out","give up"], a:3, e:"spell out = açık açık anlatmak, ayrıntılı açıklamak; kafa karıştıran bir duyurudan sonra detaylar netleştirilir. turn down (reddetmek) ve put off (ertelemek) bu amaca uymaz."},
  {id:"r-voc-phrasal-24", sub:"voc-phrasal", from:["w1-05"], q:"The company had to ---- several hundred employees after its sales fell sharply during the recession.", o:["lay off","take on","look up","set up","bring about"], a:0, e:"lay off = işten çıkarmak; satışların düşmesi işten çıkarmayı gerektirir. take on (işe almak) resesyon bağlamıyla tam ters anlam verir."},
  {id:"r-voc-phrasal-25", sub:"voc-phrasal", from:["vocab-19"], q:"Astronomers have ---- a new theory to explain why some stars suddenly lose much of their brightness.", o:["called off","broken down","put forward","got over","turned down"], a:2, e:"put forward = (fikir, teori) ortaya atmak, önermek (propose). turned down (reddetmek) ve called off (iptal etmek) “to explain” amacıyla uyuşmaz."},
  {id:"r-voc-phrasal-26", sub:"voc-phrasal", from:["vocab-18"], q:"Doctors advise patients to ---- fatty foods and sugary drinks if they want to lower their cholesterol.", o:["make up for","put up with","look forward to","run out of","cut down on"], a:4, e:"cut down on = azaltmak (reduce); kolesterolü düşürmek için yağlı yiyecekler azaltılır. put up with (katlanmak) ve look forward to (dört gözle beklemek) anlamca uymaz."},
  {id:"r-voc-phrasal-27", sub:"voc-phrasal", from:["vocab-19"], passage:"For most of the twentieth century, typewriters were an essential part of office life. When personal computers began to appear in the 1980s, many people doubted that they would ever replace such familiar machines. Within a decade, however, most offices had (1) ---- typewriters almost completely in favour of computers, and by the early 2000s only a handful of companies were still producing them.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["made up for","done away with","looked after","come across","put up with"], a:1, e:"do away with = ortadan kaldırmak, bırakmak (abolish); “in favour of computers” ve üretimin neredeyse bitmesi bunu gösterir. put up with (katlanmak) ve looked after (bakmak) “almost completely in favour of” ile çelişir."}
);
